xml.Script:
        clYellow       := 'EDFF11';
        clBlue         := '0000C8';
        clOrange       := 'FF800A';
        clLightViolett := 'FF00B0';
        clRed          := 'C80000';
        clGreen        := '009600';
        clViolett      := '7700CD';
        clGray         := '45575E';
        clWhite        := 'FFFFFF';

        mAngle := ArcTan(0.5);
        As := sin(mAngle);
        Ac := cos(mAngle);
        sAngle := PI * 2 / 5;
        for i := 1 to 5 do begin
            ax[i] := sin(sAngle * (i - 1)) * Ac;
            ay[i] := cos(sAngle * (i - 1)) * Ac;
        end;

        R := 0.9;
        Rsin := R * sin(mAngle);
        Rcos := R * cos(mAngle);

        X[3] := Rcos * sin(sAngle * 2);
        Y[3] := Rcos * cos(sAngle * 2);
        Z[3] := Rsin;

        X[6] := Rcos * sin(sAngle * 5.5);
        Y[6] := Rcos * cos(sAngle * 5.5);
        Z[6] := -Rsin;

        X[9] := Rcos * sin(sAngle * 8.5);
        Y[9] := Rcos * cos(sAngle * 8.5);
        Z[9] := -Rsin;

        dAngle := (Arctan(2) + Arcsin(2/3)) / 2;
        dAngle2 := (Arctan(2) - Arcsin(2/3)) / 2;
        K := RSin / sin(dAngle);
        Rsin := K * sin(dAngle);
        Rcos := K * cos(dAngle);
        R2sin := K * sin(dAngle2);
        R2cos := K * cos(dAngle2);

        for i := 0 to 4 do begin
            x1[i] := Rcos * sin(sAngle * (i - 0.5));
            y1[i] := Rcos * cos(sAngle * (i - 0.5));
            z1[i] := Rsin;
        end;

        for i := 5 to 9 do begin
            x1[i] := R2cos * sin(sAngle * (i - 0.5));
            y1[i] := R2cos * cos(sAngle * (i - 0.5));
            z1[i] := R2sin;
        end;

        x1[17] := Rcos * sin(sAngle * 17);
        y1[17] := Rcos * cos(sAngle * 17);
        z1[17] := -Rsin;

        D2 := R2sin;
